{
  "findings": [
    {
      "check_id": "CKV_AZURE_221",
      "title": "Ensure that Azure Function App public network access is disabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The Azure Function App does not have public network access disabled, which could expose it to unauthorized access."
    },
    {
      "check_id": "CKV_AZURE_70",
      "title": "Ensure that Function apps is only accessible over HTTPS",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The Azure Function App does not enforce HTTPS-only traffic, which could allow insecure HTTP connections."
    }
  ],
  "patched_code": "resource "azurerm_linux_function_app" "alert_function" {
  name                = "smart-manufacturing-iot-monitoring-platform-function-app-alerts"
  resource_group_name = azurerm_resource_group.smart_manufacturing.name
  location            = azurerm_resource_group.smart_manufacturing.location
  service_plan_id     = azurerm_service_plan.dashboard_plan.id
  storage_account_name       = azurerm_storage_account.function_storage.name
  storage_account_access_key = azurerm_storage_account.function_storage.primary_access_key

  site_config {
    application_stack {
      node_version = "18"
    }
    https_only = true
  }

  app_settings = {
    "FUNCTIONS_WORKER_RUNTIME" = "node"
  }

  public_network_access_enabled = false
}",
  "fix_summary": "Disabled public network access for the Azure Function App and enforced HTTPS-only traffic to ensure secure communication and prevent unauthorized access."
}
